12	+/// CPSR condition flag bits 28-31 (gbatek: ARM CPU Flags & Condition Field).
13	+pub const FLAG_NEGATIVE: u32 = 1 << 31; // N: result bit 31
14	+pub const FLAG_ZERO: u32 = 1 << 30; // Z: result was zero
15	+pub const FLAG_CARRY: u32 = 1 << 29; // C: carry out / no borrow
16	+pub const FLAG_OVERFLOW: u32 = 1 << 28; // V: signed overflow
