18	+/// Shift type from opcode bits 5-6 (ARM) or the THUMB shift opcodes.
19	+#[derive(Clone, Copy, PartialEq, Eq, Debug)]
20	+pub enum ShiftType {
21	+    LogicalLeft,      // LSL
22	+    LogicalRight,     // LSR
23	+    ArithmeticRight,  // ASR
24	+    RotateRight,      // ROR (RRX when the immediate amount is 0)
