27	+impl ShiftType {
28	+    /// Decode the 2-bit shift type field (0=LSL, 1=LSR, 2=ASR, 3=ROR).
29	+    pub fn from_bits(bits: u32) -> Self {
30	+        match bits & 3 {
31	+            0 => ShiftType::LogicalLeft,
32	+            1 => ShiftType::LogicalRight,
33	+            2 => ShiftType::ArithmeticRight,
34	+            _ => ShiftType::RotateRight,
35	+        }
36	+    }
37	+}
