39	+/// A shifted value and the shifter's carry-out.
40	+pub type ShiftResult = (u32, bool);
41	+
42	+/// Shift by an amount of 1-255, the rules for a register-specified shift
43	+/// (gbatek: ARM Opcodes: Data Processing (ALU), "Shift by Register").
44	+fn shift_by_nonzero_amount(shift_type: ShiftType, value: u32, amount: u32) -> ShiftResult {
45	+    let bit = |index: u32| (value >> index) & 1 != 0;
46	+    match shift_type {
47	+        ShiftType::LogicalLeft => match amount {
48	+            1..=31 => (value << amount, bit(32 - amount)),
49	+            32 => (0, bit(0)),
50	+            _ => (0, false),
51	+        },
52	+        ShiftType::LogicalRight => match amount {
53	+            1..=31 => (value >> amount, bit(amount - 1)),
54	+            32 => (0, bit(31)),
55	+            _ => (0, false),
56	+        },
57	+        ShiftType::ArithmeticRight => match amount {
58	+            1..=31 => (((value as i32) >> amount) as u32, bit(amount - 1)),
59	+            _ => (((value as i32) >> 31) as u32, bit(31)),
60	+        },
61	+        ShiftType::RotateRight => {
62	+            let rotation = amount % 32;
63	+            if rotation == 0 {
64	+                (value, bit(31))
65	+            } else {
66	+                (value.rotate_right(rotation), bit(rotation - 1))
67	+            }
68	+        }
69	+    }
70	+}
