72	+/// Shift by a 5-bit immediate amount, where amount 0 means LSL#0 (no shift, carry unchanged),
73	+/// LSR#32, ASR#32 or RRX (gbatek: ARM Opcodes: Data Processing (ALU), "Zero Shift Amount").
74	+pub fn shift_by_immediate(shift_type: ShiftType, value: u32, amount: u32, carry_in: bool) -> ShiftResult {
75	+    let amount = amount & 31;
76	+    if amount != 0 {
77	+        return shift_by_nonzero_amount(shift_type, value, amount);
78	+    }
79	+    match shift_type {
80	+        ShiftType::LogicalLeft => (value, carry_in),
81	+        ShiftType::LogicalRight | ShiftType::ArithmeticRight => shift_by_nonzero_amount(shift_type, value, 32),
