122	+/// `first + second + carry_in` with unsigned carry-out and signed overflow (ADD, ADC, CMN).
123	+pub fn add_with_carry(first: u32, second: u32, carry_in: bool) -> ArithmeticResult {
124	+    let wide_sum = first as u64 + second as u64 + carry_in as u64;
125	+    let value = wide_sum as u32;
126	+    // Overflow: both operands have the same sign and the result's sign differs.
127	+    let overflow = (!(first ^ second) & (first ^ value)) >> 31 != 0;
128	+    ArithmeticResult { value, carry: wide_sum > u32::MAX as u64, overflow }
129	+}
