147	+/// Whether condition field `condition` (0-15) passes for the flags in `cpsr`
148	+/// (gbatek: ARM CPU Flags & Condition Field (cond)). NV (15) never passes.
149	+pub fn condition_passed(condition: u32, cpsr: u32) -> bool {
150	+    let negative = cpsr & FLAG_NEGATIVE != 0;
151	+    let zero = cpsr & FLAG_ZERO != 0;
152	+    let carry = cpsr & FLAG_CARRY != 0;
153	+    let overflow = cpsr & FLAG_OVERFLOW != 0;
154	+    match condition & 0xF {
155	+        0x0 => zero,                          // EQ
156	+        0x1 => !zero,                         // NE
157	+        0x2 => carry,                         // CS/HS
158	+        0x3 => !carry,                        // CC/LO
159	+        0x4 => negative,                      // MI
160	+        0x5 => !negative,                     // PL
161	+        0x6 => overflow,                      // VS
162	+        0x7 => !overflow,                     // VC
163	+        0x8 => carry && !zero,                // HI
164	+        0x9 => !carry || zero,                // LS
165	+        0xA => negative == overflow,          // GE
166	+        0xB => negative != overflow,          // LT
