724	+    /// Arithmetic ops with S=1: N, Z, C and V from the result.
725	+    pub fn set_arithmetic_flags(&mut self, result: alu::ArithmeticResult) {
726	+        self.set_negative_and_zero(result.value);
727	+        self.set_carry(result.carry);
728	+        self.set_overflow(result.overflow);
729	+    }
730	+
731	+    // ---- Exceptions ----
732	+
733	+    /// Enter `exception` (gbatek: ARM CPU Exceptions): R14_<mode> = return address, SPSR_<mode> =
734	+    /// old CPSR, ARM state, new mode, I=1 (and F=1 for Reset), PC = vector.
735	+    ///
736	+    /// Undefined and SWI are raised by the decoders while executing; R14 is the next instruction
737	+    /// (return with MOVS PC,R14). Interrupt is raised between instructions; R14 is the next
738	+    /// instruction + 4 (return with SUBS PC,R14,#4). Reset leaves R14 and SPSR alone.
739	+    pub fn enter_exception(&mut self, exception: Exception) {
740	+        let next_instruction = match exception {
741	+            Exception::Interrupt => self.registers[PROGRAM_COUNTER],
742	+            _ => self.current_instruction_address().wrapping_add(self.instruction_size()),
743	+        };
744	+        let (new_mode, vector, return_address) = match exception {
745	+            Exception::Reset => (MODE_SUPERVISOR, 0x00, None),
746	+            Exception::UndefinedInstruction => (MODE_UNDEFINED, 0x04, Some(next_instruction)),
747	+            Exception::SoftwareInterrupt => (MODE_SUPERVISOR, 0x08, Some(next_instruction)),
748	+            Exception::Interrupt => (MODE_IRQ, 0x18, Some(next_instruction.wrapping_add(4))),
749	+        };
750	+        let old_cpsr = self.cpsr;
751	+        let mut new_cpsr = (old_cpsr & !(MODE_MASK | CPSR_THUMB)) | new_mode | CPSR_IRQ_DISABLE;
752	+        if exception == Exception::Reset {
753	+            new_cpsr |= CPSR_FIQ_DISABLE;
754	+        }
755	+        self.set_cpsr(new_cpsr);
756	+        if let Some(return_address) = return_address {
757	+            self.registers[LINK_REGISTER] = return_address;
758	+            self.set_spsr(old_cpsr);
759	+        }
760	+        self.branch_to(vector);
761	+    }
